macro_rules! deps {
    () => {
        ParkToken!();
        ParkResult!();
    };
}

macro_rules! park {
    () => {
        deps!();
        # [doc = " Parks the current thread in the queue associated with the given key."] # [doc = ""] # [doc = " The `validate` function is called while the queue is locked and can abort"] # [doc = " the operation by returning false. If `validate` returns true then the"] # [doc = " current thread is appended to the queue and the queue is unlocked."] # [doc = ""] # [doc = " The `before_sleep` function is called after the queue is unlocked but before"] # [doc = " the thread is put to sleep. The thread will then sleep until it is unparked"] # [doc = " or the given timeout is reached."] # [doc = ""] # [doc = " The `timed_out` function is also called while the queue is locked, but only"] # [doc = " if the timeout was reached. It is passed the key of the queue it was in when"] # [doc = " it timed out, which may be different from the original key if"] # [doc = " `unpark_requeue` was called. It is also passed a bool which indicates"] # [doc = " whether it was the last thread in the queue."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " You should only call this function with an address that you control, since"] # [doc = " you could otherwise interfere with the operation of other synchronization"] # [doc = " primitives."] # [doc = ""] # [doc = " The `validate` and `timed_out` functions are called while the queue is"] # [doc = " locked and must not panic or call into any function in `parking_lot`."] # [doc = ""] # [doc = " The `before_sleep` function is called outside the queue lock and is allowed"] # [doc = " to call `unpark_one`, `unpark_all`, `unpark_requeue` or `unpark_filter`, but"] # [doc = " it is not allowed to call `park` or panic."] # [inline] pub unsafe fn park (key : usize , validate : impl FnOnce () -> bool , before_sleep : impl FnOnce () , timed_out : impl FnOnce (usize , bool) , park_token : ParkToken , timeout : Option < Instant > ,) -> ParkResult { with_thread_data (| thread_data | { let bucket = lock_bucket (key) ; if ! validate () { bucket . mutex . unlock () ; return ParkResult :: Invalid ; } thread_data . parked_with_timeout . set (timeout . is_some ()) ; thread_data . next_in_queue . set (ptr :: null ()) ; thread_data . key . store (key , Ordering :: Relaxed) ; thread_data . park_token . set (park_token) ; thread_data . parker . prepare_park () ; if ! bucket . queue_head . get () . is_null () { (* bucket . queue_tail . get ()) . next_in_queue . set (thread_data) ; } else { bucket . queue_head . set (thread_data) ; } bucket . queue_tail . set (thread_data) ; bucket . mutex . unlock () ; before_sleep () ; let unparked = match timeout { Some (timeout) => thread_data . parker . park_until (timeout) , None => { thread_data . parker . park () ; deadlock :: on_unpark (thread_data) ; true } } ; if unparked { return ParkResult :: Unparked (thread_data . unpark_token . get ()) ; } let (key , bucket) = lock_bucket_checked (& thread_data . key) ; if ! thread_data . parker . timed_out () { bucket . mutex . unlock () ; return ParkResult :: Unparked (thread_data . unpark_token . get ()) ; } let mut link = & bucket . queue_head ; let mut current = bucket . queue_head . get () ; let mut previous = ptr :: null () ; let mut was_last_thread = true ; while ! current . is_null () { if current == thread_data { let next = (* current) . next_in_queue . get () ; link . set (next) ; if bucket . queue_tail . get () == current { bucket . queue_tail . set (previous) ; } else { let mut scan = next ; while ! scan . is_null () { if (* scan) . key . load (Ordering :: Relaxed) == key { was_last_thread = false ; break ; } scan = (* scan) . next_in_queue . get () ; } } timed_out (key , was_last_thread) ; break ; } else { if (* current) . key . load (Ordering :: Relaxed) == key { was_last_thread = false ; } link = & (* current) . next_in_queue ; previous = current ; current = link . get () ; } } debug_assert ! (! current . is_null ()) ; bucket . mutex . unlock () ; ParkResult :: TimedOut }) }
    };
}

park!();